-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-pass-through-expense-reversal-rpc.sql
-- Source SHA256: 606CE031ABCEABE337CD05518102AB8D0A0A6D5755FA7656DF8ABAA9C3F4BBF0
-- Local replay required before any staging promotion.
create or replace function finance_private.current_expense_reversal_worker_is_trusted() returns boolean language sql stable security definer set search_path=pg_catalog as $$select false$$;
create or replace function finance_private.current_actor_can_reverse_expense(p_actor_id uuid,p_expense_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$select false$$;
create or replace function finance_private.resolve_expense_reversal_context(p_expense_id uuid,p_reversal_date date) returns jsonb language sql stable security definer set search_path=pg_catalog as $$select null::jsonb$$;
create or replace function finance_api.commit_pass_through_expense_reversal(p_actor_id uuid,p_expense_id uuid,p_reversal_date date,p_expected_version bigint,p_reason_code text,p_note_hash text,p_document_ids uuid[],p_idempotency_key text,p_intent_hash text,p_correlation_id uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare e finance.pass_through_expenses%rowtype;c jsonb;v_period uuid;v_journal uuid;v_seq integer;v_count integer:=0;s record;v_accrual uuid;v_total numeric:=0;
begin
 if not finance_private.current_expense_reversal_worker_is_trusted() or not finance_private.current_actor_can_reverse_expense(p_actor_id,p_expense_id) then raise exception using errcode='42501',message='trusted expense reversal authorization required';end if;
 if p_expected_version<1 or pg_catalog.btrim(coalesce(p_reason_code,''))='' or pg_catalog.btrim(coalesce(p_idempotency_key,''))='' or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid expense reversal command';end if;
 select * into e from finance.pass_through_expenses where id=p_expense_id for update;if not found then raise exception using errcode='P0002',message='expense not found';end if;
 if e.reversal_idempotency_key is not null then if e.reversal_idempotency_key=p_idempotency_key and e.reversal_intent_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','expenseId',e.id,'journalEntryId',e.reversal_journal_entry_id,'status',e.status,'reversalDate',e.reversal_date,'shareCount',(select pg_catalog.count(*) from finance.expense_shares where pass_through_expense_id=e.id),'debitTotal',e.distributable_amount::text,'creditTotal',e.distributable_amount::text,'currencyCode',e.currency_code,'version',e.version);else return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;end if;
 if e.version<>p_expected_version or e.status<>'POSTED' or e.journal_entry_id is null then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 c:=finance_private.resolve_expense_reversal_context(e.id,p_reversal_date);if c is null or (c->>'scopeValid')::boolean is distinct from true then raise exception using errcode='23514',message='approved expense reversal context required';end if;v_period:=(c->>'financePeriodId')::uuid;
 if not exists(select 1 from finance.finance_periods fp where fp.id=v_period and fp.legal_entity_id=e.legal_entity_id and fp.mode='LIVE' and fp.status='OPEN' and p_reversal_date between fp.period_start and fp.period_end) then raise exception using errcode='23514',message='open live reversal period required';end if;
 if not exists(select 1 from finance.journal_entries j where j.id=e.journal_entry_id and j.legal_entity_id=e.legal_entity_id and j.status='POSTED') or not exists(select 1 from finance.journal_lines l where l.journal_entry_id=e.journal_entry_id) then raise exception using errcode='23514',message='posted original journal required';end if;
 if exists(select 1 from pg_catalog.unnest(coalesce(p_document_ids,'{}'::uuid[])) x left join finance.document_references d on d.id=x and d.legal_entity_id=e.legal_entity_id and d.status='ACTIVE' where d.id is null) then raise exception using errcode='23514',message='active reversal evidence required';end if;
 insert into finance.journal_entries(legal_entity_id,finance_period_id,idempotency_key,intent_hash,entry_type,business_date,posting_date,status,reversal_of_id,posted_at_utc,posted_by,created_by,correlation_id) values(e.legal_entity_id,v_period,p_idempotency_key,p_intent_hash,'PASS_THROUGH_EXPENSE_REVERSAL',p_reversal_date,p_reversal_date,'POSTED',e.journal_entry_id,pg_catalog.clock_timestamp(),p_actor_id,p_actor_id,p_correlation_id) returning id into v_journal;
 insert into finance.journal_lines(journal_entry_id,line_no,dealer_account_id,account_code,branch_id,currency_code,debit_amount,credit_amount,dimensions,created_by,correlation_id) select v_journal,l.line_no,l.dealer_account_id,l.account_code,l.branch_id,l.currency_code,l.credit_amount,l.debit_amount,l.dimensions||pg_catalog.jsonb_build_object('reversalOfJournalLineId',l.id,'originalFinancePeriodId',j.finance_period_id),p_actor_id,p_correlation_id from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id where l.journal_entry_id=e.journal_entry_id order by l.line_no;
 select coalesce(pg_catalog.max(sequence_no),0) into v_seq from finance.accruals where pass_through_expense_id=e.id;
 for s in select sh.*,a.id original_accrual_id,a.fee_definition_id,a.net_amount original_net,a.tax_amount original_tax,a.gross_amount original_gross,oi.due_date from finance.expense_shares sh join finance.accruals a on a.id=sh.accrual_id and a.pass_through_expense_id=e.id join finance.open_items oi on oi.accrual_id=a.id where sh.pass_through_expense_id=e.id order by sh.allocation_order for update of a,oi loop
  v_count:=v_count+1;v_total:=v_total+s.original_gross;insert into finance.accruals(legal_entity_id,pass_through_expense_id,dealer_account_id,branch_id,journal_entry_id,sequence_no,fee_definition_id,currency_code,net_amount,tax_amount,gross_amount,status,reversal_of_id,created_by,correlation_id) values(e.legal_entity_id,e.id,s.dealer_account_id,s.branch_id,v_journal,v_seq+v_count,s.fee_definition_id,e.currency_code,-s.original_net,-s.original_tax,-s.original_gross,'POSTED',s.original_accrual_id,p_actor_id,p_correlation_id) returning id into v_accrual;
  insert into finance.open_items(legal_entity_id,accrual_id,dealer_account_id,branch_id,due_date,currency_code,item_type,original_amount,allocated_amount,open_amount,status,created_by,correlation_id) values(e.legal_entity_id,v_accrual,s.dealer_account_id,s.branch_id,p_reversal_date,e.currency_code,'CREDIT',s.original_gross,0,s.original_gross,'OPEN',p_actor_id,p_correlation_id);
 end loop;
 if v_count=0 or v_total<>e.distributable_amount then raise exception using errcode='23514',message='expense share reversal control mismatch';end if;
 update finance.pass_through_expenses set status='REVERSED',reversal_journal_entry_id=v_journal,reversal_idempotency_key=p_idempotency_key,reversal_intent_hash=p_intent_hash,reversal_date=p_reversal_date,reversal_reason_code=p_reason_code,reversal_note_hash=p_note_hash,reversed_by=p_actor_id,reversed_at_utc=pg_catalog.clock_timestamp(),version=version+1,correlation_id=p_correlation_id where id=e.id;
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(e.legal_entity_id,'finance.expense','finance.pass-through-expense.reversed','PASS_THROUGH_EXPENSE',e.id,e.version+1,pg_catalog.jsonb_build_object('expenseId',e.id,'reversalJournalEntryId',v_journal,'originalJournalEntryId',e.journal_entry_id),p_intent_hash,'PENDING',p_correlation_id);
 insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,reason_code,after_hash,integrity_hash,safe_context,correlation_id) values(e.legal_entity_id,p_actor_id,'USER','PASS_THROUGH_EXPENSE_REVERSED','PASS_THROUGH_EXPENSE',e.id,p_reason_code,p_intent_hash,pg_catalog.md5(e.id::text||p_intent_hash||p_correlation_id::text),pg_catalog.jsonb_build_object('noteHash',p_note_hash,'documentCount',coalesce(pg_catalog.array_length(p_document_ids,1),0),'originalJournalEntryId',e.journal_entry_id),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','REVERSED','expenseId',e.id,'journalEntryId',v_journal,'status','REVERSED','reversalDate',p_reversal_date,'shareCount',v_count,'debitTotal',v_total::text,'creditTotal',v_total::text,'currencyCode',e.currency_code,'version',e.version+1);
end$$;
revoke all on function finance_api.commit_pass_through_expense_reversal(uuid,uuid,date,bigint,text,text,uuid[],text,text,uuid) from public,anon,authenticated;
